-- =============================================================================================
-- hand-written: constraints, helpers, guards, stage gate, deferred invariants, least privilege, RLS
-- and the revision effective_from back-fill.
-- =============================================================================================

-- ---- single-row constraints ---------------------------------------------------------------------
ALTER TABLE "people_leave_accounts"
  ADD CONSTRAINT people_leave_accounts_unit CHECK ("unit" = 'HOURS'),
  ADD CONSTRAINT people_leave_accounts_version_positive CHECK ("version" >= 1);

ALTER TABLE "people_leave_buckets"
  ADD CONSTRAINT people_leave_buckets_state CHECK ("state" IN ('FUTURE', 'OPEN', 'CLOSED', 'FROZEN')),
  ADD CONSTRAINT people_leave_buckets_service_period CHECK ("service_period" >= 1),
  -- A leave year (or a transition year, D-P3C-21) is between one day and one leap year long.
  ADD CONSTRAINT people_leave_buckets_year CHECK ("year_end" > "year_start" AND "year_end" - "year_start" <= 366),
  ADD CONSTRAINT people_leave_buckets_opened CHECK (("state" = 'FUTURE') = ("opened_at" IS NULL) OR ("state" = 'FROZEN')),
  ADD CONSTRAINT people_leave_buckets_closed CHECK (("state" = 'CLOSED') = ("closed_at" IS NOT NULL)),
  ADD CONSTRAINT people_leave_buckets_version_positive CHECK ("version" >= 1);

ALTER TABLE "people_leave_transactions"
  ADD CONSTRAINT people_leave_transactions_kind CHECK ("kind" IN (
    'OPENING_BALANCE', 'IMPORT', 'YEAR_OPEN', 'ACCRUAL', 'RESERVE', 'CONSUME', 'RELEASE', 'REVERSE_CONSUMPTION',
    'ADJUSTMENT', 'CORRECTION', 'CARRY_PROPAGATION', 'EXPIRY', 'PAYOUT', 'FREEZE')),
  ADD CONSTRAINT people_leave_transactions_basis CHECK ("actor_basis" IN (
    'DERIVED', 'SELF', 'LINE_MANAGER', 'LEAVE_MANAGER', 'LEAVE_MANAGER_OVERRIDE', 'AUTO_NO_APPROVAL', 'SOLE_OWNER_SELF',
    'LEAVE_CORRECT_GRANT', 'SOLE_AUTHORISER')),
  ADD CONSTRAINT people_leave_transactions_source CHECK ("source_kind" IN (
    'LEAVE_REQUEST', 'POLICY_ACCRUAL', 'YEAR_BOUNDARY', 'MANUAL', 'IMPORT_BATCH', 'PAYROLL', 'TRANSACTION', 'EMPLOYMENT')),
  ADD CONSTRAINT people_leave_transactions_key CHECK (char_length("idempotency_key") BETWEEN 1 AND 200),
  ADD CONSTRAINT people_leave_transactions_request_hash CHECK ("request_hash" IS NULL OR "request_hash" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT people_leave_transactions_external_ref CHECK ("external_ref" IS NULL OR char_length("external_ref") BETWEEN 1 AND 200),
  ADD CONSTRAINT people_leave_transactions_reason_code CHECK ("reason_code" IS NULL OR "reason_code" IN (
    'OPENING', 'IMPORT', 'DATA_ENTRY_ERROR', 'POLICY_MISCONFIGURED', 'HOURS_BASIS_CHANGED', 'LEAVE_NOT_TAKEN', 'GOODWILL',
    'AGREEMENT', 'CARRY_CAP', 'PAYOUT_TERMINATION', 'PAYOUT_CASH_OUT', 'UNIT_CONVERSION', 'OTHER')),
  ADD CONSTRAINT people_leave_transactions_reason_text CHECK (
    ("reason_text" IS NULL OR char_length(btrim("reason_text")) BETWEEN 1 AND 500)
    AND ("reason_code" IS DISTINCT FROM 'OTHER' OR char_length(btrim(coalesce("reason_text", ''))) >= 10)
    AND ("reason_text" IS NULL OR "reason_code" IS NOT NULL)),
  -- Manual kinds and "the leave did not happen" always carry a reason (§D.2); a payout its payroll reference.
  ADD CONSTRAINT people_leave_transactions_reason_required CHECK (
    "kind" NOT IN ('OPENING_BALANCE', 'IMPORT', 'ADJUSTMENT', 'CORRECTION', 'EXPIRY', 'PAYOUT', 'REVERSE_CONSUMPTION') OR "reason_code" IS NOT NULL),
  ADD CONSTRAINT people_leave_transactions_payout_ref CHECK ("kind" <> 'PAYOUT' OR "external_ref" IS NOT NULL),
  -- Every transaction bumps the account it posts to (created at 1), so it records version 2 or later.
  ADD CONSTRAINT people_leave_transactions_account_version CHECK ("account_version" >= 2),
  ADD CONSTRAINT people_leave_transactions_not_self_related CHECK ("related_transaction_id" IS DISTINCT FROM "id");

ALTER TABLE "people_leave_entries"
  ADD CONSTRAINT people_leave_entries_book CHECK ("book" IN ('BALANCE', 'RESERVED')),
  ADD CONSTRAINT people_leave_entries_kind_book CHECK (
    ("book" = 'BALANCE' AND "kind" IN ('OPENING_BALANCE', 'IMPORT', 'GRANT', 'ACCRUAL', 'CARRY_OUT', 'CARRY_IN', 'EXPIRY',
                                       'CONSUMPTION', 'ADJUSTMENT', 'REVERSAL', 'PAYOUT', 'WRITE_OFF'))
    OR ("book" = 'RESERVED' AND "kind" IN ('RESERVATION', 'RESERVATION_RELEASE'))),
  ADD CONSTRAINT people_leave_entries_hours_nonzero CHECK ("hours" <> 0),
  -- Fixed signs (§C.6, §D.1). EXPIRY is negative in every transaction kind (v1.3). CARRY_*, OPENING_BALANCE,
  -- IMPORT, ADJUSTMENT and REVERSAL take either sign; their pair and transaction invariants constrain them.
  ADD CONSTRAINT people_leave_entries_sign CHECK (
    CASE
      WHEN "kind" IN ('GRANT', 'ACCRUAL', 'RESERVATION', 'WRITE_OFF') THEN "hours" > 0
      WHEN "kind" IN ('CONSUMPTION', 'PAYOUT', 'RESERVATION_RELEASE', 'EXPIRY') THEN "hours" < 0
      ELSE true
    END),
  ADD CONSTRAINT people_leave_entries_accrual_period CHECK (
    ("kind" = 'ACCRUAL') = ("period_start" IS NOT NULL AND "period_end" IS NOT NULL)
    AND ("period_start" IS NULL) = ("period_end" IS NULL)
    AND ("period_start" IS NULL OR "period_start" < "period_end")),
  ADD CONSTRAINT people_leave_entries_reversal CHECK (("kind" = 'REVERSAL') = ("reverses_entry_id" IS NOT NULL)),
  ADD CONSTRAINT people_leave_entries_release_reason CHECK (
    ("kind" = 'RESERVATION_RELEASE') = ("release_reason" IS NOT NULL)
    AND ("release_reason" IS NULL OR "release_reason" IN ('CONSUMED', 'CANCELLED', 'FROZEN'))),
  ADD CONSTRAINT people_leave_entries_expiry_reason CHECK (
    ("kind" = 'EXPIRY') = ("expiry_reason" IS NOT NULL)
    AND ("expiry_reason" IS NULL OR "expiry_reason" IN ('CARRY_CAP', 'MAX_BALANCE', 'MANUAL', 'POLICY_EXPIRY'))),
  ADD CONSTRAINT people_leave_entries_settles CHECK (("reservation_entry_id" IS NOT NULL) = ("kind" IN ('RESERVATION_RELEASE', 'CONSUMPTION'))),
  ADD CONSTRAINT people_leave_entries_pair CHECK (("pair_entry_id" IS NOT NULL) = ("kind" IN ('CARRY_OUT', 'CARRY_IN'))),
  ADD CONSTRAINT people_leave_entries_leave_date CHECK (
    ("kind" NOT IN ('RESERVATION', 'RESERVATION_RELEASE', 'CONSUMPTION') OR "leave_date" IS NOT NULL)
    AND ("kind" IN ('RESERVATION', 'RESERVATION_RELEASE', 'CONSUMPTION', 'REVERSAL') OR "leave_date" IS NULL)),
  ADD CONSTRAINT people_leave_entries_consumption_date CHECK ("kind" <> 'CONSUMPTION' OR "applies_on" = "leave_date"),
  ADD CONSTRAINT people_leave_entries_hours_per_day CHECK ("hours_per_day" IS NULL OR "hours_per_day" > 0),
  ADD CONSTRAINT people_leave_entries_not_self CHECK (
    "reverses_entry_id" IS DISTINCT FROM "id" AND "reservation_entry_id" IS DISTINCT FROM "id" AND "pair_entry_id" IS DISTINCT FROM "id");

ALTER TABLE "people_leave_authorisations"
  ADD CONSTRAINT people_leave_authorisations_capability CHECK ("capability" IN ('LEAVE_CORRECT', 'LEAVE_VIEW')),
  ADD CONSTRAINT people_leave_authorisations_revoked CHECK (("revoked_at" IS NULL) = ("revoked_by_id" IS NULL));

-- ---- idempotency and settlement uniques (§D.3) ----------------------------------------------------
-- Only one OPEN bucket per account and service period (V-03).
CREATE UNIQUE INDEX "people_leave_buckets_one_open_key" ON "people_leave_buckets" ("business_id", "account_id", "service_period") WHERE "state" = 'OPEN';
-- One reversal per entry; one release and one consumption per reservation date.
CREATE UNIQUE INDEX "people_leave_entries_one_reversal_key" ON "people_leave_entries" ("business_id", "reverses_entry_id") WHERE "reverses_entry_id" IS NOT NULL;
CREATE UNIQUE INDEX "people_leave_entries_one_release_key" ON "people_leave_entries" ("business_id", "reservation_entry_id") WHERE "kind" = 'RESERVATION_RELEASE';
CREATE UNIQUE INDEX "people_leave_entries_one_consumption_key" ON "people_leave_entries" ("business_id", "reservation_entry_id") WHERE "kind" = 'CONSUMPTION';
-- One reservation per transaction and date (with the rs:{requestId} key: one per request and date).
CREATE UNIQUE INDEX "people_leave_entries_one_reservation_key" ON "people_leave_entries" ("business_id", "transaction_id", "leave_date") WHERE "kind" = 'RESERVATION';
-- One accrual per bucket and period start (periods never cross a bucket, so per account and service
-- period), and at most one accrual entry per transaction (an ACCRUAL, or the final one of a FREEZE).
CREATE UNIQUE INDEX "people_leave_entries_one_accrual_key" ON "people_leave_entries" ("business_id", "bucket_id", "period_start") WHERE "kind" = 'ACCRUAL';
CREATE UNIQUE INDEX "people_leave_entries_accrual_per_transaction_key" ON "people_leave_entries" ("business_id", "transaction_id") WHERE "kind" = 'ACCRUAL';
-- One GRANT per bucket; one CARRY_OUT, one CARRY_IN and one year-end lapse per bucket and transaction.
CREATE UNIQUE INDEX "people_leave_entries_one_grant_key" ON "people_leave_entries" ("business_id", "bucket_id") WHERE "kind" = 'GRANT';
CREATE UNIQUE INDEX "people_leave_entries_one_carry_out_key" ON "people_leave_entries" ("business_id", "bucket_id", "transaction_id") WHERE "kind" = 'CARRY_OUT';
CREATE UNIQUE INDEX "people_leave_entries_one_carry_in_key" ON "people_leave_entries" ("business_id", "bucket_id", "transaction_id") WHERE "kind" = 'CARRY_IN';
CREATE UNIQUE INDEX "people_leave_entries_one_lapse_key" ON "people_leave_entries" ("business_id", "bucket_id", "transaction_id") WHERE "kind" = 'EXPIRY' AND "expiry_reason" = 'CARRY_CAP';
-- One active authorisation per member, capability and scope (C5 uses it; the table stays empty in C1).
CREATE UNIQUE INDEX "people_leave_authorisations_active_key" ON "people_leave_authorisations"
  ("business_id", "user_id", "capability", coalesce("department_id", '00000000-0000-0000-0000-000000000000'::uuid)) WHERE "revoked_at" IS NULL;
-- Lookups the guards and the read policy make by reference.
CREATE INDEX "people_leave_entries_reservation_idx" ON "people_leave_entries" ("business_id", "reservation_entry_id") WHERE "reservation_entry_id" IS NOT NULL;
CREATE INDEX "people_leave_entries_pair_idx" ON "people_leave_entries" ("business_id", "pair_entry_id") WHERE "pair_entry_id" IS NOT NULL;

-- ---- helpers --------------------------------------------------------------------------------------
-- All SECURITY INVOKER: they run as bos_app under forced RLS, so they only ever see the current tenant.

-- The business's today in its own time zone; NULL without a tenant context (callers fail closed).
CREATE FUNCTION people_leave_business_today() RETURNS date
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog, public AS $$
  SELECT (now() AT TIME ZONE b.time_zone)::date FROM businesses b
   WHERE b.id = nullif(current_setting('app.business_id', true), '')::uuid
$$;

-- A leave type's current sensitivity flag; an unreadable type counts as sensitive (fail closed).
CREATE FUNCTION people_leave_type_sensitive(p_leave_type uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog, public AS $$
  SELECT coalesce((SELECT t.sensitive FROM people_leave_types t
                    WHERE t.business_id = nullif(current_setting('app.business_id', true), '')::uuid AND t.id = p_leave_type), true)
$$;

-- Who may read ledger rows of (employee, leave type) at a level (§I.3, D-P3C-06, D-P3C-34). The actor comes
-- from app.user_id only; a missing setting, a suspended or absent membership, or an unknown level is false.
-- C1 ships the fail-closed branches only:
--   * roles that hold people:manage and people:read_sensitive (OWNER, ADMIN; drift test against
--     modules/access/server/permissions.ts): every employee, both levels, sensitive types included;
--   * the employee whose user link is the session user: their own rows, both levels, sensitive included.
-- The line-manager branch (C4, with the approve key) and the LEAVE_CORRECT grant branch (C5) are added by
-- the migrations that introduce them. Until then everybody else (MANAGER, MEMBER, people:read) sees nothing.
-- p_sensitive is (row snapshot OR current type flag); the C1 branches see sensitive rows anyway, the C4/C5
-- branches will test it.
CREATE FUNCTION people_leave_can_read(p_employee uuid, p_leave_type uuid, p_sensitive boolean, p_level text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  v_actor uuid := nullif(current_setting('app.user_id', true), '')::uuid;
  v_business uuid := nullif(current_setting('app.business_id', true), '')::uuid;
  v_role text;
BEGIN
  IF v_actor IS NULL OR v_business IS NULL OR p_level IS NULL OR p_level NOT IN ('BALANCE', 'DETAIL') THEN
    RETURN false;
  END IF;
  SELECT m.role::text INTO v_role FROM memberships m
   WHERE m.business_id = v_business AND m.user_id = v_actor AND m.status = 'ACTIVE';
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  IF v_role IN ('OWNER', 'ADMIN') THEN
    RETURN true;
  END IF;
  IF EXISTS (SELECT 1 FROM people_employees e WHERE e.business_id = v_business AND e.id = p_employee AND e.user_id = v_actor) THEN
    RETURN true;
  END IF;
  RETURN false;
END $$;

-- Correction authorisations (detail level): OWNER and ADMIN, and the holder of a grant. Empty in C1.
CREATE FUNCTION people_leave_can_read_authorisation(p_user uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog, public AS $$
  SELECT EXISTS (SELECT 1 FROM memberships m
                  WHERE m.business_id = nullif(current_setting('app.business_id', true), '')::uuid
                    AND m.user_id = nullif(current_setting('app.user_id', true), '')::uuid AND m.status = 'ACTIVE'
                    AND (m.role IN ('OWNER', 'ADMIN') OR m.user_id = p_user))
$$;

-- Lock proof (§C.6, T-C05): the account row's current version was written by this database transaction,
-- i.e. this transaction bumped it (an UPDATE, which holds the row lock until commit). NULL when the
-- account is not visible. A bump made inside a savepoint carries a subtransaction id and is refused.
CREATE FUNCTION people_leave_account_locked(p_business uuid, p_account uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog, public AS $$
  SELECT a.xmin::text = (pg_current_xact_id()::text::bigint % 4294967296)::text
    FROM people_leave_accounts a WHERE a.business_id = p_business AND a.id = p_account
$$;

-- ---- accounts -------------------------------------------------------------------------------------
-- Created at version 1 by a writer who can read the whole account; afterwards only the version advances,
-- by exactly one, and every bump must be used by exactly one ledger transaction (deferred check below,
-- plus the unique (account, account_version) on transactions).
CREATE FUNCTION people_leave_accounts_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.version <> 1 THEN
      RAISE EXCEPTION 'a leave account is created at version 1' USING ERRCODE = 'PE016';
    END IF;
    IF NOT people_leave_can_read(NEW.employee_id, NEW.leave_type_id, true, 'DETAIL') THEN
      RAISE EXCEPTION 'the writer cannot read this leave account' USING ERRCODE = 'PE019';
    END IF;
    NEW.created_at := now();
    NEW.updated_at := now();
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW) - ARRAY['version', 'updated_at']) <> (to_jsonb(OLD) - ARRAY['version', 'updated_at']) THEN
    RAISE EXCEPTION 'a leave account''s identity is fixed' USING ERRCODE = 'PE013';
  END IF;
  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'a leave account''s version advances by one per ledger transaction' USING ERRCODE = 'PE009';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION people_leave_accounts_guard() FROM PUBLIC;
CREATE TRIGGER people_leave_accounts_guard BEFORE INSERT OR UPDATE ON "people_leave_accounts"
  FOR EACH ROW EXECUTE FUNCTION people_leave_accounts_guard();

-- At commit: the bump to NEW.version is recorded by a ledger transaction (V-06 enforced at write time).
CREATE FUNCTION people_leave_accounts_check() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM people_leave_transactions t
                  WHERE t.business_id = NEW.business_id AND t.account_id = NEW.id AND t.account_version = NEW.version) THEN
    RAISE EXCEPTION 'a leave account was bumped without a ledger transaction' USING ERRCODE = 'PE017';
  END IF;
  RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION people_leave_accounts_check() FROM PUBLIC;
CREATE CONSTRAINT TRIGGER people_leave_accounts_check AFTER UPDATE ON "people_leave_accounts"
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION people_leave_accounts_check();

-- ---- buckets --------------------------------------------------------------------------------------
-- Created (FUTURE or OPEN) and moved only inside a ledger transaction of this database transaction on the
-- same account, under the account lock. States: FUTURE→OPEN and OPEN→CLOSED only in a YEAR_OPEN;
-- FUTURE|OPEN→FROZEN only in a FREEZE; FROZEN and CLOSED are final. Years of one account and service
-- period never overlap. Only state, its stamps and the version change.
CREATE FUNCTION people_leave_buckets_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  v_locked boolean;
  v_needed text;
BEGIN
  v_locked := people_leave_account_locked(NEW.business_id, NEW.account_id);
  IF v_locked IS NULL THEN
    RAISE EXCEPTION 'leave_reference_not_visible: account' USING ERRCODE = 'PE018';
  ELSIF NOT v_locked THEN
    RAISE EXCEPTION 'the leave account lock is not held' USING ERRCODE = 'PE014';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.state NOT IN ('FUTURE', 'OPEN') OR NEW.version <> 1 OR NEW.closed_at IS NOT NULL THEN
      RAISE EXCEPTION 'a leave year is created FUTURE or OPEN at version 1' USING ERRCODE = 'PE016';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM people_leave_transactions t
                    WHERE t.business_id = NEW.business_id AND t.account_id = NEW.account_id AND t.recorded_xid = pg_current_xact_id()) THEN
      RAISE EXCEPTION 'a leave year is created inside a ledger transaction' USING ERRCODE = 'PE016';
    END IF;
    IF EXISTS (SELECT 1 FROM people_leave_buckets b
                WHERE b.business_id = NEW.business_id AND b.account_id = NEW.account_id AND b.service_period = NEW.service_period
                  AND daterange(b.year_start, b.year_end) && daterange(NEW.year_start, NEW.year_end)) THEN
      RAISE EXCEPTION 'leave years of one account and service period may not overlap' USING ERRCODE = 'PE016';
    END IF;
    NEW.opened_at := CASE WHEN NEW.state = 'OPEN' THEN now() END;
    NEW.created_at := now();
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW) - ARRAY['state', 'opened_at', 'closed_at', 'version']) <> (to_jsonb(OLD) - ARRAY['state', 'opened_at', 'closed_at', 'version']) THEN
    RAISE EXCEPTION 'a leave year''s account, period and dates are fixed' USING ERRCODE = 'PE013';
  END IF;
  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'a leave year''s version advances by one on every change' USING ERRCODE = 'PE009';
  END IF;
  IF (OLD.state, NEW.state) IN (('FUTURE', 'OPEN'), ('OPEN', 'CLOSED')) THEN
    v_needed := 'YEAR_OPEN';
  ELSIF (OLD.state, NEW.state) IN (('FUTURE', 'FROZEN'), ('OPEN', 'FROZEN')) THEN
    v_needed := 'FREEZE';
  ELSE
    RAISE EXCEPTION 'leave year state % cannot become %', OLD.state, NEW.state USING ERRCODE = 'PE016';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM people_leave_transactions t
                  WHERE t.business_id = NEW.business_id AND t.account_id = NEW.account_id AND t.kind = v_needed
                    AND t.recorded_xid = pg_current_xact_id()) THEN
    RAISE EXCEPTION 'leave year state % → % needs a % transaction', OLD.state, NEW.state, v_needed USING ERRCODE = 'PE016';
  END IF;
  NEW.opened_at := CASE WHEN NEW.state = 'OPEN' THEN now() ELSE OLD.opened_at END;
  NEW.closed_at := CASE WHEN NEW.state = 'CLOSED' THEN now() END;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION people_leave_buckets_guard() FROM PUBLIC;
CREATE TRIGGER people_leave_buckets_guard BEFORE INSERT OR UPDATE ON "people_leave_buckets"
  FOR EACH ROW EXECUTE FUNCTION people_leave_buckets_guard();

-- ---- transactions ---------------------------------------------------------------------------------
-- Insert only. The database sets actor, business date, recorded time and xid, the account version and the
-- sensitivity; the statement cannot choose them. Kind/basis matrix (§I.2a): a derived kind needs DERIVED, a
-- request kind a P3-B basis, a manual kind a manual basis (manual bases are re-derived from the session by
-- the C5 guard; the stage gate below refuses request and manual kinds in C1). System keys are derived
-- from facts and checked here, so a derived posting cannot reuse a free-form key.
CREATE FUNCTION people_leave_transactions_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  v_actor uuid := nullif(current_setting('app.user_id', true), '')::uuid;
  v_today date := people_leave_business_today();
  v_version int;
  v_locked boolean;
  v_related_sensitive boolean;
  v_uuid constant text := '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}';
  v_date constant text := '[0-9]{4}-[0-9]{2}-[0-9]{2}';
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'leave ledger transactions are immutable' USING ERRCODE = 'PE013';
  END IF;
  IF v_actor IS NULL OR v_today IS NULL THEN
    RAISE EXCEPTION 'a leave ledger posting needs a user and a business context' USING ERRCODE = 'PE019';
  END IF;
  SELECT a.version, people_leave_account_locked(a.business_id, a.id) INTO v_version, v_locked
    FROM people_leave_accounts a WHERE a.business_id = NEW.business_id AND a.id = NEW.account_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'leave_reference_not_visible: account' USING ERRCODE = 'PE018';
  END IF;
  IF NOT v_locked THEN
    RAISE EXCEPTION 'the leave account lock is not held' USING ERRCODE = 'PE014';
  END IF;
  -- Every invariant checked at commit sums rows of this account, so the writer must be able to read all of
  -- them, sensitive included (a partial view could make a wrong sum look right). Stricter than §C.6a step 2
  -- and equivalent for every writer C1 allows.
  IF NOT people_leave_can_read(NEW.employee_id, NEW.leave_type_id, true, 'DETAIL') THEN
    RAISE EXCEPTION 'the writer cannot read this leave account' USING ERRCODE = 'PE019';
  END IF;

  IF NEW.kind IN ('ACCRUAL', 'YEAR_OPEN', 'CONSUME', 'FREEZE', 'CARRY_PROPAGATION') THEN
    IF NEW.actor_basis <> 'DERIVED' THEN
      RAISE EXCEPTION 'a derived posting has basis DERIVED' USING ERRCODE = 'PE016';
    END IF;
    IF NEW.request_hash IS NOT NULL OR NEW.reason_code IS NOT NULL OR NEW.external_ref IS NOT NULL
       OR NEW.source_id IS NOT NULL OR NEW.checked_by_user_id IS NOT NULL THEN
      RAISE EXCEPTION 'a derived posting carries no request hash, reason, reference, source id or checker' USING ERRCODE = 'PE016';
    END IF;
    IF NEW.source_kind <> (CASE NEW.kind WHEN 'ACCRUAL' THEN 'POLICY_ACCRUAL' WHEN 'YEAR_OPEN' THEN 'YEAR_BOUNDARY'
                                         WHEN 'CONSUME' THEN 'LEAVE_REQUEST' WHEN 'FREEZE' THEN 'EMPLOYMENT' ELSE 'TRANSACTION' END) THEN
      RAISE EXCEPTION 'source kind % does not match a % posting', NEW.source_kind, NEW.kind USING ERRCODE = 'PE016';
    END IF;
    IF (NEW.kind = 'CARRY_PROPAGATION') <> (NEW.related_transaction_id IS NOT NULL) THEN
      RAISE EXCEPTION 'exactly a carry propagation names the transaction that caused it' USING ERRCODE = 'PE016';
    END IF;
    IF NOT coalesce(CASE NEW.kind
      WHEN 'ACCRUAL' THEN NEW.idempotency_key ~ ('^ac:' || NEW.account_id::text || ':[1-9][0-9]{0,4}:' || v_date || '$')
      WHEN 'YEAR_OPEN' THEN NEW.idempotency_key ~ ('^yo:' || v_uuid || '$')
      WHEN 'CONSUME' THEN NEW.idempotency_key ~ ('^cs:' || NEW.account_id::text || ':' || v_date || ':' || v_date || '$')
      WHEN 'FREEZE' THEN NEW.idempotency_key ~ ('^fz:' || NEW.account_id::text || ':[1-9][0-9]{0,4}$')
      ELSE NEW.idempotency_key = 'cp:' || NEW.related_transaction_id::text || ':' || substr(NEW.idempotency_key, 41)
           AND NEW.idempotency_key ~ ('^cp:' || v_uuid || ':' || v_uuid || '$')
    END, false) THEN
      RAISE EXCEPTION 'idempotency key does not have the derived % shape', NEW.kind USING ERRCODE = 'PE016';
    END IF;
  ELSIF NEW.kind IN ('RESERVE', 'RELEASE', 'REVERSE_CONSUMPTION') THEN
    IF NEW.actor_basis NOT IN ('SELF', 'LINE_MANAGER', 'LEAVE_MANAGER', 'LEAVE_MANAGER_OVERRIDE', 'AUTO_NO_APPROVAL', 'SOLE_OWNER_SELF') THEN
      RAISE EXCEPTION 'a request posting has a P3-B basis' USING ERRCODE = 'PE016';
    END IF;
  ELSE
    IF NEW.actor_basis NOT IN ('LEAVE_MANAGER', 'LEAVE_CORRECT_GRANT', 'SOLE_AUTHORISER') THEN
      RAISE EXCEPTION 'a manual posting has a manual basis' USING ERRCODE = 'PE016';
    END IF;
  END IF;

  -- Sensitivity (§C.6a): computed, never trusted; the statement may raise it, never lower it.
  NEW.sensitive := coalesce(NEW.sensitive, false) OR people_leave_type_sensitive(NEW.leave_type_id);
  IF NEW.related_transaction_id IS NOT NULL THEN
    SELECT t.sensitive INTO v_related_sensitive FROM people_leave_transactions t
     WHERE t.business_id = NEW.business_id AND t.id = NEW.related_transaction_id AND t.account_id = NEW.account_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'leave_reference_not_visible: related transaction' USING ERRCODE = 'PE018';
    END IF;
    NEW.sensitive := NEW.sensitive OR v_related_sensitive;
  END IF;

  NEW.actor_user_id := v_actor;
  NEW.posted_on := v_today;
  NEW.recorded_at := now();
  NEW.recorded_xid := pg_current_xact_id();
  NEW.account_version := v_version;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION people_leave_transactions_guard() FROM PUBLIC;
CREATE TRIGGER people_leave_transactions_guard BEFORE INSERT OR UPDATE ON "people_leave_transactions"
  FOR EACH ROW EXECUTE FUNCTION people_leave_transactions_guard();

-- Stage gate (§I.2a point 4): C1 accepts only the derived kinds it builds and tests. Each later package
-- replaces this function together with its own backstop (C3/B2 request kinds, C5 manual kinds).
CREATE FUNCTION people_leave_transactions_stage_gate() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF NEW.kind NOT IN ('ACCRUAL', 'YEAR_OPEN', 'CONSUME', 'FREEZE', 'CARRY_PROPAGATION') THEN
    RAISE EXCEPTION 'leave ledger transaction kind % is not enabled in this stage', NEW.kind USING ERRCODE = 'PE015';
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION people_leave_transactions_stage_gate() FROM PUBLIC;
CREATE TRIGGER people_leave_transactions_stage_gate BEFORE INSERT ON "people_leave_transactions"
  FOR EACH ROW EXECUTE FUNCTION people_leave_transactions_stage_gate();

-- At commit: every transaction has at least one entry (V-07), except a FREEZE that only changes year states;
-- a YEAR_OPEN leaves the year its key names OPEN.
CREATE FUNCTION people_leave_transactions_check() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF NEW.kind <> 'FREEZE' AND NOT EXISTS (SELECT 1 FROM people_leave_entries e WHERE e.business_id = NEW.business_id AND e.transaction_id = NEW.id) THEN
    RAISE EXCEPTION 'a leave ledger transaction has at least one entry' USING ERRCODE = 'PE017';
  END IF;
  IF NEW.kind = 'YEAR_OPEN' AND NOT EXISTS (
       SELECT 1 FROM people_leave_buckets b
        WHERE b.business_id = NEW.business_id AND b.account_id = NEW.account_id AND b.id::text = substr(NEW.idempotency_key, 4) AND b.state = 'OPEN') THEN
    RAISE EXCEPTION 'a year opening leaves its year OPEN' USING ERRCODE = 'PE017';
  END IF;
  RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION people_leave_transactions_check() FROM PUBLIC;
CREATE CONSTRAINT TRIGGER people_leave_transactions_check AFTER INSERT ON "people_leave_transactions"
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION people_leave_transactions_check();

-- ---- entries --------------------------------------------------------------------------------------
-- Insert only, into a ledger transaction created by this same database transaction, under the account lock.
-- Checks the kind/transaction matrix (§I.2a), the year's state, the dates, the cited rows (mirror, settle,
-- derived key binding) and computes the sensitivity (§C.6a). Pair, settlement, closing, lapse and
-- containment rules that need the other rows of the transaction are checked at commit (below).
CREATE FUNCTION people_leave_entries_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  t people_leave_transactions;
  b people_leave_buckets;
  c people_leave_entries;
  v_locked boolean;
  v_unit text;
  v_method text;
  v_allowed boolean;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'leave ledger entries are immutable' USING ERRCODE = 'PE013';
  END IF;
  SELECT * INTO t FROM people_leave_transactions
   WHERE business_id = NEW.business_id AND id = NEW.transaction_id AND account_id = NEW.account_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'leave_reference_not_visible: transaction' USING ERRCODE = 'PE018';
  END IF;
  IF t.recorded_xid <> pg_current_xact_id() THEN
    RAISE EXCEPTION 'entries are added only by the database transaction that created their ledger transaction' USING ERRCODE = 'PE016';
  END IF;
  v_locked := people_leave_account_locked(NEW.business_id, NEW.account_id);
  IF v_locked IS NOT TRUE THEN
    RAISE EXCEPTION 'the leave account lock is not held' USING ERRCODE = 'PE014';
  END IF;
  SELECT * INTO b FROM people_leave_buckets WHERE business_id = NEW.business_id AND id = NEW.bucket_id AND account_id = NEW.account_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'leave_reference_not_visible: leave year' USING ERRCODE = 'PE018';
  END IF;

  -- Stage-gated vocabulary.
  IF NEW.kind = 'WRITE_OFF' THEN
    RAISE EXCEPTION 'WRITE_OFF is not enabled until D-P3C-11 is decided' USING ERRCODE = 'PE015';
  END IF;
  IF NEW.expiry_reason = 'POLICY_EXPIRY' THEN
    RAISE EXCEPTION 'POLICY_EXPIRY is not enabled until D-P3C-15 is decided' USING ERRCODE = 'PE015';
  END IF;
  IF NEW.hours_per_day IS NOT NULL THEN
    RAISE EXCEPTION 'a days-to-hours basis is not enabled until the revised D-P3C-23 basis is accepted' USING ERRCODE = 'PE015';
  END IF;
  SELECT r.rules ->> 'unit', r.rules ->> 'entitlement_method' INTO v_unit, v_method FROM people_leave_policy_revisions r
   WHERE r.business_id = NEW.business_id AND r.policy_id = NEW.policy_id AND r.version = NEW.policy_version;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'leave_reference_not_visible: policy revision' USING ERRCODE = 'PE018';
  END IF;
  IF v_unit IS DISTINCT FROM 'HOURS' THEN
    RAISE EXCEPTION 'postings under a DAYS policy need the revised D-P3C-23 conversion basis (not enabled)' USING ERRCODE = 'PE015';
  END IF;
  IF v_method IS NOT DISTINCT FROM 'NONE' OR (NEW.kind = 'GRANT' AND v_method <> 'GRANT') OR (NEW.kind = 'ACCRUAL' AND v_method <> 'ACCRUAL') THEN
    RAISE EXCEPTION 'entry % does not fit the policy''s entitlement method %', NEW.kind, v_method USING ERRCODE = 'PE016';
  END IF;

  -- Kind matrix (§I.2a): which entries each transaction kind may contain.
  v_allowed := coalesce(CASE t.kind
    WHEN 'ACCRUAL' THEN NEW.kind = 'ACCRUAL' OR (NEW.kind = 'EXPIRY' AND NEW.expiry_reason = 'MAX_BALANCE')
    WHEN 'YEAR_OPEN' THEN NEW.kind IN ('GRANT', 'CARRY_OUT', 'CARRY_IN', 'WRITE_OFF') OR (NEW.kind = 'EXPIRY' AND NEW.expiry_reason = 'CARRY_CAP')
    WHEN 'CONSUME' THEN NEW.kind = 'CONSUMPTION' OR (NEW.kind = 'RESERVATION_RELEASE' AND NEW.release_reason = 'CONSUMED')
    WHEN 'FREEZE' THEN NEW.kind = 'ACCRUAL' OR (NEW.kind = 'EXPIRY' AND NEW.expiry_reason = 'MAX_BALANCE')
                       OR (NEW.kind = 'RESERVATION_RELEASE' AND NEW.release_reason = 'FROZEN')
    WHEN 'CARRY_PROPAGATION' THEN NEW.kind IN ('CARRY_OUT', 'CARRY_IN', 'REVERSAL') OR (NEW.kind = 'EXPIRY' AND NEW.expiry_reason = 'CARRY_CAP')
    WHEN 'RESERVE' THEN NEW.kind IN ('RESERVATION', 'CONSUMPTION') OR (NEW.kind = 'RESERVATION_RELEASE' AND NEW.release_reason = 'CONSUMED')
    WHEN 'RELEASE' THEN NEW.kind = 'RESERVATION_RELEASE' AND NEW.release_reason = 'CANCELLED'
    WHEN 'REVERSE_CONSUMPTION' THEN NEW.kind = 'REVERSAL'
    WHEN 'ADJUSTMENT' THEN NEW.kind = 'ADJUSTMENT'
    WHEN 'CORRECTION' THEN NEW.kind IN ('REVERSAL', 'ADJUSTMENT')
    WHEN 'EXPIRY' THEN NEW.kind = 'EXPIRY' AND NEW.expiry_reason = 'MANUAL'
    WHEN 'PAYOUT' THEN NEW.kind = 'PAYOUT'
    WHEN 'OPENING_BALANCE' THEN NEW.kind = 'OPENING_BALANCE'
    WHEN 'IMPORT' THEN NEW.kind = 'IMPORT'
    ELSE false END, false);  -- a NULL reason is not a match
  IF NOT v_allowed THEN
    RAISE EXCEPTION 'a % transaction cannot contain a % entry', t.kind, NEW.kind USING ERRCODE = 'PE016';
  END IF;

  -- The year's state allows the posting (§C.6 guard; final states only take what may follow them).
  IF b.state = 'FUTURE' AND NEW.book <> 'RESERVED' THEN
    RAISE EXCEPTION 'a future leave year holds reservations only' USING ERRCODE = 'PE016';
  ELSIF b.state = 'FROZEN' AND t.kind NOT IN ('FREEZE', 'PAYOUT') THEN
    RAISE EXCEPTION 'a frozen leave year takes no further postings' USING ERRCODE = 'PE016';
  ELSIF b.state = 'CLOSED' AND t.kind NOT IN ('ADJUSTMENT', 'CORRECTION', 'CARRY_PROPAGATION')
        AND NOT (t.kind = 'YEAR_OPEN' AND NEW.kind IN ('CARRY_OUT', 'EXPIRY', 'WRITE_OFF') AND b.closed_at = now()
                 AND (SELECT x.xmin::text::bigint FROM people_leave_buckets x WHERE x.business_id = b.business_id AND x.id = b.id)
                     = pg_current_xact_id()::text::bigint % 4294967296) THEN
    -- The closing YEAR_OPEN posts the year's carry-out and lapse after it closes the year, in the same transaction.
    RAISE EXCEPTION 'a closed leave year takes only corrections and their propagation' USING ERRCODE = 'PE016';
  END IF;
  IF NEW.leave_date IS NOT NULL AND NOT (NEW.leave_date >= b.year_start AND NEW.leave_date < b.year_end) THEN
    RAISE EXCEPTION 'leave date % is outside its leave year', NEW.leave_date USING ERRCODE = 'PE016';
  END IF;

  -- Derived entries: dates and key binding (§D.2, §G.4, §G.6).
  IF NEW.kind = 'ACCRUAL' THEN
    IF NEW.period_start < b.year_start OR NEW.period_end > b.year_end OR NEW.applies_on <> NEW.period_end - 1 THEN
      RAISE EXCEPTION 'an accrual period lies inside its leave year and applies on its last day' USING ERRCODE = 'PE016';
    END IF;
    IF t.kind = 'ACCRUAL' AND t.idempotency_key <> format('ac:%s:%s:%s', NEW.account_id, b.service_period, to_char(NEW.period_start, 'YYYY-MM-DD')) THEN
      RAISE EXCEPTION 'an accrual posting''s key names its account, service period and period start' USING ERRCODE = 'PE016';
    END IF;
  ELSIF NEW.kind = 'GRANT' THEN
    IF t.idempotency_key <> 'yo:' || NEW.bucket_id::text OR NEW.applies_on <> b.year_start THEN
      RAISE EXCEPTION 'a grant is posted into the year its opening names, on the year''s first day' USING ERRCODE = 'PE016';
    END IF;
  ELSIF NEW.kind = 'CARRY_IN' THEN
    IF NEW.applies_on <> b.year_start OR (t.kind = 'YEAR_OPEN' AND t.idempotency_key <> 'yo:' || NEW.bucket_id::text) THEN
      RAISE EXCEPTION 'a carry-in is posted into the opening year, on its first day' USING ERRCODE = 'PE016';
    END IF;
  ELSIF NEW.kind = 'CARRY_OUT' OR (NEW.kind = 'EXPIRY' AND NEW.expiry_reason = 'CARRY_CAP') THEN
    IF NEW.applies_on <> b.year_end - 1 THEN
      RAISE EXCEPTION 'a carry-out or year-end lapse applies on the closing year''s last day' USING ERRCODE = 'PE016';
    END IF;
  END IF;

  NEW.sensitive := coalesce(NEW.sensitive, false) OR t.sensitive OR people_leave_type_sensitive(NEW.leave_type_id);

  -- Settlement of one reservation date: same year and date, exactly the reserved hours (§C.6).
  IF NEW.reservation_entry_id IS NOT NULL THEN
    SELECT * INTO c FROM people_leave_entries WHERE business_id = NEW.business_id AND id = NEW.reservation_entry_id AND account_id = NEW.account_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'leave_reference_not_visible: reservation' USING ERRCODE = 'PE018';
    END IF;
    IF c.kind <> 'RESERVATION' OR c.bucket_id <> NEW.bucket_id OR c.leave_date <> NEW.leave_date OR NEW.hours <> -c.hours THEN
      RAISE EXCEPTION 'a settlement cites one reservation date of the same year, for exactly its hours' USING ERRCODE = 'PE016';
    END IF;
    IF (NEW.kind = 'CONSUMPTION' OR NEW.release_reason = 'CONSUMED') AND c.leave_date > people_leave_business_today() THEN
      RAISE EXCEPTION 'a leave date is consumed only once it has arrived' USING ERRCODE = 'PE016';
    END IF;
    IF NEW.release_reason = 'CONSUMED' AND NEW.applies_on <> greatest(c.leave_date, c.applies_on) THEN
      RAISE EXCEPTION 'a release for consumption applies on the later of the leave date and the reservation date' USING ERRCODE = 'PE016';
    END IF;
    NEW.sensitive := NEW.sensitive OR c.sensitive;
  END IF;

  -- Reversal: the exact mirror of one BALANCE entry; carry entries are corrected by propagation, a year-end
  -- lapse is reversed only by propagation, a reversal is never reversed (§C.6, §G.7).
  IF NEW.reverses_entry_id IS NOT NULL THEN
    SELECT * INTO c FROM people_leave_entries WHERE business_id = NEW.business_id AND id = NEW.reverses_entry_id AND account_id = NEW.account_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'leave_reference_not_visible: reversed entry' USING ERRCODE = 'PE018';
    END IF;
    IF NEW.hours <> -c.hours OR NEW.bucket_id <> c.bucket_id OR NEW.book <> c.book OR NEW.leave_date IS DISTINCT FROM c.leave_date THEN
      RAISE EXCEPTION 'a reversal mirrors its entry exactly (hours, year, book, leave date)' USING ERRCODE = 'PE016';
    END IF;
    IF c.kind IN ('CARRY_OUT', 'CARRY_IN', 'REVERSAL', 'RESERVATION', 'RESERVATION_RELEASE') THEN
      RAISE EXCEPTION 'a % entry is not reversed', c.kind USING ERRCODE = 'PE016';
    END IF;
    IF (c.kind = 'EXPIRY' AND c.expiry_reason = 'CARRY_CAP') <> (t.kind = 'CARRY_PROPAGATION') THEN
      RAISE EXCEPTION 'a year-end lapse is reversed only, and only it, by carry propagation' USING ERRCODE = 'PE016';
    END IF;
    IF t.kind = 'REVERSE_CONSUMPTION' AND c.kind <> 'CONSUMPTION' THEN
      RAISE EXCEPTION 'reversing a consumption reverses consumptions only' USING ERRCODE = 'PE016';
    END IF;
    NEW.sensitive := NEW.sensitive OR c.sensitive;
  END IF;

  -- Carry pair: both halves are inserted by one statement, so the second may not exist yet; equality of
  -- the pair (including sensitivity) is checked at commit.
  IF NEW.pair_entry_id IS NOT NULL THEN
    SELECT * INTO c FROM people_leave_entries WHERE business_id = NEW.business_id AND id = NEW.pair_entry_id AND account_id = NEW.account_id;
    IF FOUND THEN
      NEW.sensitive := NEW.sensitive OR c.sensitive;
    END IF;
  END IF;

  NEW.recorded_at := now();
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION people_leave_entries_guard() FROM PUBLIC;
CREATE TRIGGER people_leave_entries_guard BEFORE INSERT OR UPDATE ON "people_leave_entries"
  FOR EACH ROW EXECUTE FUNCTION people_leave_entries_guard();

-- Year invariants of one bucket (§C.6, §F.4 I-4), checked at commit whenever a CLOSED year is touched:
-- BALANCE and RESERVED both sum to 0; at most one unreversed year-end lapse; the carry and lapse entries
-- cite one policy revision; the net lapse (≤ 0) is exactly closing − carry, i.e. when hours lapse the carry
-- equals the limit (CAPPED: cap, NONE: 0, UNLIMITED: never a lapse), and a positive carry never exceeds
-- the limit. A negative closing balance carried in full is accepted (D-P3C-11 recommendation; WRITE_OFF,
-- the alternative, is refused until it is decided). Policies here are HOURS (DAYS postings are refused).
CREATE FUNCTION people_leave_check_year(p_business uuid, p_bucket uuid) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  v_state text;
  v_balance numeric;
  v_reserved numeric;
  v_unreversed int;
  v_lapse numeric;
  v_carry numeric;
  v_revisions int;
  v_rules jsonb;
  v_limit numeric;
BEGIN
  SELECT b.state INTO v_state FROM people_leave_buckets b WHERE b.business_id = p_business AND b.id = p_bucket;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'leave_reference_not_visible: leave year' USING ERRCODE = 'PE018';
  END IF;
  IF v_state <> 'CLOSED' THEN
    RETURN;
  END IF;
  SELECT coalesce(sum(e.hours) FILTER (WHERE e.book = 'BALANCE'), 0), coalesce(sum(e.hours) FILTER (WHERE e.book = 'RESERVED'), 0)
    INTO v_balance, v_reserved FROM people_leave_entries e WHERE e.business_id = p_business AND e.bucket_id = p_bucket;
  IF v_balance <> 0 OR v_reserved <> 0 THEN
    RAISE EXCEPTION 'a closed leave year sums to zero (balance %, reserved %)', v_balance, v_reserved USING ERRCODE = 'PE017';
  END IF;
  WITH lapse AS (
    SELECT e.id, e.hours FROM people_leave_entries e
     WHERE e.business_id = p_business AND e.bucket_id = p_bucket AND e.kind = 'EXPIRY' AND e.expiry_reason = 'CARRY_CAP'
  ), lapse_reversal AS (
    SELECT r.hours, r.reverses_entry_id FROM people_leave_entries r JOIN lapse l ON r.reverses_entry_id = l.id
     WHERE r.business_id = p_business
  )
  SELECT (SELECT count(*) FROM lapse l WHERE NOT EXISTS (SELECT 1 FROM lapse_reversal x WHERE x.reverses_entry_id = l.id)),
         (SELECT coalesce(sum(hours), 0) FROM lapse) + (SELECT coalesce(sum(hours), 0) FROM lapse_reversal)
    INTO v_unreversed, v_lapse;
  SELECT -coalesce(sum(e.hours), 0) INTO v_carry FROM people_leave_entries e
   WHERE e.business_id = p_business AND e.bucket_id = p_bucket AND e.kind = 'CARRY_OUT';
  IF v_unreversed > 1 THEN
    RAISE EXCEPTION 'a closed leave year has at most one unreversed year-end lapse' USING ERRCODE = 'PE017';
  END IF;
  SELECT count(DISTINCT (e.policy_id, e.policy_version)), min(r.rules::text)::jsonb INTO v_revisions, v_rules
    FROM people_leave_entries e
    JOIN people_leave_policy_revisions r ON r.business_id = e.business_id AND r.policy_id = e.policy_id AND r.version = e.policy_version
   WHERE e.business_id = p_business AND e.bucket_id = p_bucket
     AND (e.kind = 'CARRY_OUT' OR (e.kind = 'EXPIRY' AND e.expiry_reason = 'CARRY_CAP'));
  IF v_revisions > 1 THEN
    RAISE EXCEPTION 'a closed leave year''s carry and lapse cite one policy revision' USING ERRCODE = 'PE017';
  END IF;
  IF v_lapse < 0 OR v_carry > 0 THEN
    IF v_revisions = 0 THEN
      RAISE EXCEPTION 'a carry or lapse cites its policy revision' USING ERRCODE = 'PE017';
    END IF;
    v_limit := CASE v_rules ->> 'carryover'
      WHEN 'NONE' THEN 0
      WHEN 'CAPPED' THEN (v_rules ->> 'carryover_cap')::numeric
      ELSE NULL END;
    IF v_lapse < 0 AND (v_limit IS NULL OR v_carry <> v_limit) THEN
      RAISE EXCEPTION 'hours lapse only above the carry limit: lapse %, carry %, limit %', v_lapse, v_carry, coalesce(v_limit::text, 'unlimited')
        USING ERRCODE = 'PE017';
    END IF;
    IF v_carry > 0 AND v_limit IS NOT NULL AND v_carry > v_limit THEN
      RAISE EXCEPTION 'carry % exceeds the limit %', v_carry, v_limit USING ERRCODE = 'PE017';
    END IF;
  END IF;
END $$;
REVOKE ALL ON FUNCTION people_leave_check_year(uuid, uuid) FROM PUBLIC;

-- At commit, per entry: consumption ⇔ release(CONSUMED) in the same transaction; carry pairs mutual, equal
-- and opposite, into the next year of the same service period; carry-out and lapse only in a year that is
-- CLOSED, carry-in and grants only in a year that is not FUTURE; sensitivity never lower than the
-- transaction or a cited row, and the transaction never lower than its entries (§C.6a step 3); the year
-- invariants when the year is CLOSED.
CREATE FUNCTION people_leave_entries_check() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  e people_leave_entries;
  p people_leave_entries;
  v_tx_sensitive boolean;
  v_state text;
  v_year_start date;
  v_year_end date;
  v_period int;
  v_pair_state text;
  v_pair_start date;
  v_pair_end date;
  v_pair_period int;
  v_n int;
BEGIN
  SELECT * INTO e FROM people_leave_entries WHERE business_id = NEW.business_id AND id = NEW.id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'leave_reference_not_visible: entry' USING ERRCODE = 'PE018';
  END IF;
  SELECT t.sensitive INTO v_tx_sensitive FROM people_leave_transactions t WHERE t.business_id = e.business_id AND t.id = e.transaction_id;
  IF e.sensitive AND NOT v_tx_sensitive THEN
    RAISE EXCEPTION 'a transaction is at least as sensitive as every entry it contains' USING ERRCODE = 'PE017';
  END IF;
  SELECT b.state, b.year_start, b.year_end, b.service_period INTO v_state, v_year_start, v_year_end, v_period
    FROM people_leave_buckets b WHERE b.business_id = e.business_id AND b.id = e.bucket_id;

  IF e.kind = 'CONSUMPTION' OR e.release_reason = 'CONSUMED' THEN
    SELECT count(*) INTO v_n FROM people_leave_entries o
     WHERE o.business_id = e.business_id AND o.transaction_id = e.transaction_id AND o.reservation_entry_id = e.reservation_entry_id
       AND o.id <> e.id AND o.bucket_id = e.bucket_id AND o.leave_date = e.leave_date AND o.hours = e.hours
       AND (CASE WHEN e.kind = 'CONSUMPTION' THEN o.kind = 'RESERVATION_RELEASE' AND o.release_reason = 'CONSUMED' ELSE o.kind = 'CONSUMPTION' END);
    IF v_n <> 1 THEN
      RAISE EXCEPTION 'a consumption and its release for consumption are posted together' USING ERRCODE = 'PE017';
    END IF;
  END IF;

  IF e.kind IN ('CARRY_OUT', 'CARRY_IN') THEN
    SELECT * INTO p FROM people_leave_entries WHERE business_id = e.business_id AND id = e.pair_entry_id AND account_id = e.account_id;
    IF NOT FOUND OR p.pair_entry_id IS DISTINCT FROM e.id OR p.transaction_id <> e.transaction_id OR p.hours <> -e.hours
       OR p.kind <> (CASE e.kind WHEN 'CARRY_OUT' THEN 'CARRY_IN' ELSE 'CARRY_OUT' END) OR p.sensitive <> e.sensitive THEN
      RAISE EXCEPTION 'a carry-out and its carry-in are one mutual, equal and opposite pair' USING ERRCODE = 'PE017';
    END IF;
    SELECT b.state, b.year_start, b.year_end, b.service_period INTO v_pair_state, v_pair_start, v_pair_end, v_pair_period
      FROM people_leave_buckets b WHERE b.business_id = p.business_id AND b.id = p.bucket_id;
    IF v_pair_period <> v_period
       OR (e.kind = 'CARRY_OUT' AND v_pair_start <> v_year_end) OR (e.kind = 'CARRY_IN' AND v_year_start <> v_pair_end) THEN
      RAISE EXCEPTION 'hours are carried into the next leave year of the same service period' USING ERRCODE = 'PE017';
    END IF;
  END IF;

  IF (e.kind = 'CARRY_OUT' OR (e.kind = 'EXPIRY' AND e.expiry_reason = 'CARRY_CAP')) AND v_state <> 'CLOSED' THEN
    RAISE EXCEPTION 'carry-out and the year-end lapse belong to a closed leave year' USING ERRCODE = 'PE017';
  END IF;
  IF e.kind IN ('CARRY_IN', 'GRANT') AND v_state = 'FUTURE' THEN
    RAISE EXCEPTION 'entitlement goes into an opened leave year' USING ERRCODE = 'PE017';
  END IF;

  IF e.reverses_entry_id IS NOT NULL OR e.reservation_entry_id IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM people_leave_entries c WHERE c.business_id = e.business_id
                 AND c.id IN (e.reverses_entry_id, e.reservation_entry_id) AND c.sensitive AND NOT e.sensitive) THEN
      RAISE EXCEPTION 'an entry is at least as sensitive as every entry it cites' USING ERRCODE = 'PE017';
    END IF;
  END IF;

  IF v_state = 'CLOSED' THEN
    PERFORM people_leave_check_year(e.business_id, e.bucket_id);
  END IF;
  RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION people_leave_entries_check() FROM PUBLIC;
CREATE CONSTRAINT TRIGGER people_leave_entries_check AFTER INSERT ON "people_leave_entries"
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION people_leave_entries_check();

-- At commit, per year that changed state: a year closed by this transaction satisfies the year invariants.
CREATE FUNCTION people_leave_buckets_check() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  PERFORM people_leave_check_year(NEW.business_id, NEW.id);
  RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION people_leave_buckets_check() FROM PUBLIC;
CREATE CONSTRAINT TRIGGER people_leave_buckets_check AFTER UPDATE ON "people_leave_buckets"
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION people_leave_buckets_check();

-- ---- correction authorisations (C5) ---------------------------------------------------------------
-- The table exists so the read policy and grants are in place before any row can (D-P3C-34); writing it is
-- not enabled until C5 ships the grant guard (OWNER/ADMIN grantor, MANAGER grantee, revoke once, D-P3C-19).
-- C5 must also settle how a grant interacts with removing the member (the FK to memberships blocks a
-- membership delete while a grant row exists).
CREATE FUNCTION people_leave_authorisations_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  RAISE EXCEPTION 'leave correction authorisations are not enabled in this stage' USING ERRCODE = 'PE015';
END $$;
REVOKE ALL ON FUNCTION people_leave_authorisations_guard() FROM PUBLIC;
CREATE TRIGGER people_leave_authorisations_guard BEFORE INSERT OR UPDATE ON "people_leave_authorisations"
  FOR EACH ROW EXECUTE FUNCTION people_leave_authorisations_guard();

-- ---- policy revisions: effective_from (D-P3-25 rule 1, §C.8) ---------------------------------------
-- Same guard as P3-A, plus: the database sets effective_from to the business's today and marks it RECORDED.
CREATE OR REPLACE FUNCTION people_leave_policy_revisions_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  p people_leave_policies;
  v_today date;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'policy revisions are append-only' USING ERRCODE = 'PE004';
  END IF;
  SELECT * INTO p FROM people_leave_policies WHERE business_id = NEW.business_id AND id = NEW.policy_id;
  IF NOT FOUND OR p.version <> NEW.version THEN
    RAISE EXCEPTION 'a revision records the policy''s current version' USING ERRCODE = 'PE004';
  END IF;
  SELECT (now() AT TIME ZONE b.time_zone)::date INTO v_today FROM businesses b WHERE b.id = NEW.business_id;
  IF v_today IS NULL THEN
    RAISE EXCEPTION 'a revision needs its business''s date' USING ERRCODE = 'PE004';
  END IF;
  NEW.rules := people_leave_policy_rules(p);
  NEW.recorded_by_id := p.updated_by_id;
  NEW.recorded_at := now();
  NEW.effective_from := v_today;
  NEW.effective_from_basis := 'RECORDED';
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION people_leave_policy_revisions_guard() FROM PUBLIC;

-- ---- least privilege ------------------------------------------------------------------------------
-- No DELETE or TRUNCATE anywhere. Transactions and entries: insert only. Accounts: only the version bump.
-- Buckets: only the state, its stamps and the version. Authorisations: read only in C1. Nothing for bos_jobs.
REVOKE ALL ON "people_leave_accounts", "people_leave_buckets", "people_leave_transactions", "people_leave_entries", "people_leave_authorisations" FROM bos_app;
GRANT SELECT, INSERT ON "people_leave_accounts", "people_leave_buckets", "people_leave_transactions", "people_leave_entries" TO bos_app;
GRANT SELECT ON "people_leave_authorisations" TO bos_app;
GRANT UPDATE ("version", "updated_at") ON "people_leave_accounts" TO bos_app;
GRANT UPDATE ("state", "opened_at", "closed_at", "version") ON "people_leave_buckets" TO bos_app;
REVOKE ALL ON FUNCTION people_leave_business_today(), people_leave_type_sensitive(uuid), people_leave_can_read(uuid, uuid, boolean, text),
  people_leave_can_read_authorisation(uuid), people_leave_account_locked(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION people_leave_business_today(), people_leave_type_sensitive(uuid), people_leave_can_read(uuid, uuid, boolean, text),
  people_leave_can_read_authorisation(uuid), people_leave_account_locked(uuid, uuid), people_leave_check_year(uuid, uuid) TO bos_app;

-- ---- row-level security ---------------------------------------------------------------------------
-- Every table: the standard permissive tenant_isolation policy, plus a RESTRICTIVE read policy (§I.3,
-- D-P3C-34) present before any row can exist. Balance level: accounts, buckets, entries. Detail level:
-- transactions, authorisations. The read policies never read child rows; sensitivity is the row's own
-- immutable snapshot OR the type's current flag.
ALTER TABLE "people_leave_accounts" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "people_leave_accounts" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "people_leave_accounts" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
CREATE POLICY leave_read ON "people_leave_accounts" AS RESTRICTIVE FOR SELECT TO bos_app
  USING (people_leave_can_read("employee_id", "leave_type_id", people_leave_type_sensitive("leave_type_id"), 'BALANCE'));

ALTER TABLE "people_leave_buckets" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "people_leave_buckets" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "people_leave_buckets" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
CREATE POLICY leave_read ON "people_leave_buckets" AS RESTRICTIVE FOR SELECT TO bos_app
  USING (people_leave_can_read("employee_id", "leave_type_id", people_leave_type_sensitive("leave_type_id"), 'BALANCE'));

ALTER TABLE "people_leave_transactions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "people_leave_transactions" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "people_leave_transactions" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
CREATE POLICY leave_read ON "people_leave_transactions" AS RESTRICTIVE FOR SELECT TO bos_app
  USING (people_leave_can_read("employee_id", "leave_type_id", "sensitive" OR people_leave_type_sensitive("leave_type_id"), 'DETAIL'));

ALTER TABLE "people_leave_entries" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "people_leave_entries" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "people_leave_entries" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
CREATE POLICY leave_read ON "people_leave_entries" AS RESTRICTIVE FOR SELECT TO bos_app
  USING (people_leave_can_read("employee_id", "leave_type_id", "sensitive" OR people_leave_type_sensitive("leave_type_id"), 'BALANCE'));

ALTER TABLE "people_leave_authorisations" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "people_leave_authorisations" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "people_leave_authorisations" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
CREATE POLICY leave_read ON "people_leave_authorisations" AS RESTRICTIVE FOR SELECT TO bos_app
  USING (people_leave_can_read_authorisation("user_id"));

-- ---- revision effective_from back-fill (§J.2, D-P3C-27; an existing-data transformation) ----------
-- >>> backfill-effective-from (tests/integration/people-leave-ledger.test.ts runs this block verbatim as bos_owner)
-- Existing revisions get the business date of recorded_at in the business's CURRENT time zone, marked
-- INFERRED: exact unless the business changed its time zone after the revision (the preflight lists those
-- businesses; D-P3C-35). No ledger amount may depend on an INFERRED date (§J.2 step 3): ledger postings and
-- opening-balance cutovers start on or after the apply date + 1 day (enforced by the C2 engine and the C5
-- import guard; C1 posts no engine amounts).
-- Both tables force RLS and give the owner role no policy, so under FORCE the owner sees no row and the
-- UPDATE would silently change nothing. FORCE is lifted for the owner on the two tables the statement reads,
-- for this block only, and restored before the transaction ends; the revision guard (append-only) is
-- disabled for the same span. ALTER TABLE holds ACCESS EXCLUSIVE on both until COMMIT, so no other session
-- observes the gap, and lock_timeout (3 s) aborts the whole migration rather than queueing behind traffic.
-- bos_app is not the owner, so its policies apply throughout either way.
ALTER TABLE "people_leave_policy_revisions" NO FORCE ROW LEVEL SECURITY;
ALTER TABLE "businesses" NO FORCE ROW LEVEL SECURITY;
ALTER TABLE "people_leave_policy_revisions" DISABLE TRIGGER people_leave_policy_revisions_guard;
DO $$
DECLARE
  v_before bigint;
  v_updated bigint;
BEGIN
  SELECT count(*) INTO v_before FROM people_leave_policy_revisions;
  UPDATE people_leave_policy_revisions r
     SET effective_from = (r.recorded_at AT TIME ZONE b.time_zone)::date, effective_from_basis = 'INFERRED'
    FROM businesses b
   WHERE b.id = r.business_id;
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> v_before OR EXISTS (SELECT 1 FROM people_leave_policy_revisions WHERE effective_from IS NULL) THEN
    RAISE EXCEPTION 'effective_from back-fill incomplete: % of % revision rows updated', v_updated, v_before;
  END IF;
  RAISE NOTICE 'people_leave_policy_revisions effective_from back-filled: % rows (INFERRED)', v_updated;
END $$;
ALTER TABLE "people_leave_policy_revisions" ENABLE TRIGGER people_leave_policy_revisions_guard;
ALTER TABLE "businesses" FORCE ROW LEVEL SECURITY;
ALTER TABLE "people_leave_policy_revisions" FORCE ROW LEVEL SECURITY;
DO $$
BEGIN
  IF (SELECT count(*) FROM pg_class WHERE oid IN ('public.businesses'::regclass, 'public.people_leave_policy_revisions'::regclass)
        AND relrowsecurity AND relforcerowsecurity) <> 2 THEN
    RAISE EXCEPTION 'forced row-level security not restored on businesses and people_leave_policy_revisions';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'public.people_leave_policy_revisions'::regclass
                   AND tgname = 'people_leave_policy_revisions_guard' AND tgenabled = 'O') THEN
    RAISE EXCEPTION 'people_leave_policy_revisions_guard not re-enabled';
  END IF;
END $$;
-- <<< backfill-effective-from
ALTER TABLE "people_leave_policy_revisions"
  ALTER COLUMN "effective_from" SET NOT NULL,
  ADD CONSTRAINT people_leave_policy_revisions_effective_basis CHECK ("effective_from_basis" IN ('RECORDED', 'INFERRED'));
-- The policy in force on a date D is max(version) WHERE effective_from <= D (§C.8).
CREATE INDEX "people_leave_policy_revisions_effective_idx" ON "people_leave_policy_revisions" ("business_id", "policy_id", "effective_from", "version");

